CREATE TABLE `window_warranties` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`window_id` integer NOT NULL,`status` text DEFAULT 'pending' NOT NULL,`coverage_start` text,`coverage_end` text,`terms_en` text DEFAULT '' NOT NULL,`terms_zh` text DEFAULT '' NOT NULL,`updated_by` integer NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL); CREATE UNIQUE INDEX `window_warranties_window_id_unique` ON `window_warranties` (`window_id`); CREATE INDEX `window_warranties_window_idx` ON `window_warranties` (`window_id`);
CREATE TABLE `customer_service_cases` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`property_id` integer NOT NULL,`room_id` integer NOT NULL,`window_id` integer NOT NULL,`customer_user_id` integer NOT NULL,`category` text NOT NULL,`description` text NOT NULL,`status` text DEFAULT 'submitted' NOT NULL,`appointment_start` text,`appointment_end` text,`customer_resolution` text DEFAULT '' NOT NULL,`idempotency_key` text NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL); CREATE UNIQUE INDEX `customer_service_cases_idempotency_key_unique` ON `customer_service_cases` (`idempotency_key`); CREATE INDEX `customer_service_cases_window_idx` ON `customer_service_cases` (`window_id`,`created_at`); CREATE INDEX `customer_service_cases_status_idx` ON `customer_service_cases` (`status`);
CREATE TABLE `customer_service_messages` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`case_id` integer NOT NULL,`author_user_id` integer NOT NULL,`body` text NOT NULL,`internal_only` integer DEFAULT false NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL); CREATE INDEX `customer_service_messages_case_idx` ON `customer_service_messages` (`case_id`,`created_at`);
CREATE TABLE `customer_service_media` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`case_id` integer NOT NULL,`uploaded_by` integer NOT NULL,`object_key` text NOT NULL,`content_type` text NOT NULL,`file_name` text NOT NULL,`size_bytes` integer NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL); CREATE UNIQUE INDEX `customer_service_media_object_key_unique` ON `customer_service_media` (`object_key`); CREATE INDEX `customer_service_media_case_idx` ON `customer_service_media` (`case_id`);
CREATE TABLE `customer_visible_documents` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`property_id` integer,`window_id` integer,`order_reference` text DEFAULT '' NOT NULL,`document_type` text NOT NULL,`title_en` text NOT NULL,`title_zh` text NOT NULL,`url` text NOT NULL,`customer_visible` integer DEFAULT false NOT NULL,`published_by` integer NOT NULL,`published_at` text NOT NULL); CREATE INDEX `customer_visible_documents_property_idx` ON `customer_visible_documents` (`property_id`); CREATE INDEX `customer_visible_documents_window_idx` ON `customer_visible_documents` (`window_id`);
